libsrc='''def runs_of(grid, val, horizontal=True, minlen=2):
    """Maximal runs of a value with at least minlen cells, as (row, c0, c1) if horizontal else (col, r0, r1)."""
    h, w = len(grid), len(grid[0])
    res = []
    outer, inner = (h, w) if horizontal else (w, h)
    for a in range(outer):
        b = 0
        while b < inner:
            cell = grid[a][b] if horizontal else grid[b][a]
            if cell == val:
                s = b
                while b < inner and (grid[a][b] if horizontal else grid[b][a]) == val:
                    b += 1
                if b - s >= minlen:
                    res.append((a, s, b - 1) if horizontal else (a, s, b - 1))
            else:
                b += 1
    return res

def longest_block(idxs):
    """The longest contiguous block of a sorted list of indices."""
    if not idxs:
        return []
    blocks, cur = [], [idxs[0]]
    for i in idxs[1:]:
        if i == cur[-1] + 1:
            cur.append(i)
        else:
            blocks.append(cur); cur = [i]
    blocks.append(cur)
    return max(blocks, key=len)

def fill_l_frame(grid, frame_val=5):
    """For each L (a frame line of frame_val with a patterned arm at a corner), fill its bounding rectangle: the frame line stays frame_val, the arm pattern repeats across the rectangle."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    for kind, c, r0, r1 in runs_of(grid, frame_val, horizontal=False):
        for sgn in (1, -1):
            if not (0 <= c + sgn < w):
                continue
            idxs = [r for r in range(r0, r1 + 1) if grid[r][c + sgn] != 0]
            block = longest_block(idxs)
            if not block:
                continue
            a0, a1 = block[0], block[-1]
            acols = []
            cc = c + sgn
            while 0 <= cc < w and any(grid[r][cc] != 0 for r in range(a0, a1 + 1)):
                acols.append(cc); cc += sgn
            if not acols:
                continue
            ah = a1 - a0 + 1
            rtop, rbot = min(r0, a0), max(r1, a1)
            cleft, cright = min(c, min(acols)), max(c, max(acols))
            for rr in range(rtop, rbot + 1):
                for cc2 in range(cleft, cright + 1):
                    if cc2 == c:
                        out[rr][cc2] = frame_val
                    else:
                        out[rr][cc2] = grid[a0 + (rr - rtop) % ah][cc2]
            break
    for kind, r, c0, c1 in runs_of(grid, frame_val, horizontal=True):
        for sgn in (1, -1):
            if not (0 <= r + sgn < h):
                continue
            idxs = [cc for cc in range(c0, c1 + 1) if grid[r + sgn][cc] != 0]
            block = longest_block(idxs)
            if not block:
                continue
            b0, b1 = block[0], block[-1]
            arows = []
            rr = r + sgn
            while 0 <= rr < h and any(grid[rr][cc] != 0 for cc in range(b0, b1 + 1)):
                arows.append(rr); rr += sgn
            if not arows:
                continue
            aw = b1 - b0 + 1
            rtop, rbot = min(r, min(arows)), max(r, max(arows))
            cleft, cright = min(c0, b0), max(c1, b1)
            for rr in range(rtop, rbot + 1):
                for cc in range(cleft, cright + 1):
                    if rr == r:
                        out[rr][cc] = frame_val
                    else:
                        out[rr][cc] = grid[rr][b0 + (cc - cleft) % aw]
            break
    return out
